WITH payload AS (
 SELECT value AS item FROM jsonb_array_elements($DADYOOM$[{"order":1,"title":"القراءة: الدرس الأول: أسرة جاسم (1)","lessonType":"reading","objective":"يقرأ جملتين عن الأسرة ويحدد أفرادها","content":"القراءة: الدرس الأول: أسرة جاسم (1)\n\nأهداف التعلّم\n• يقرأ جملتين عن الأسرة ويحدد أفرادها.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nأقرأ بهدوء: «أنا جاسم. هذه أسرتي. هذا أبي، وهذه أمي». هذه جمل تدريبية من تأليف ضاديوم وليست نص «أسرة جاسم» في الكتاب. أبدأ من اليمين، وأتوقف عند النقطة، ثم أعيد القراءة بصوت واضح.\n\nأقرأ وألاحظ\nأنا جاسم. هذا أبي. هذه أمي. نحن أسرة.\n\nأتدرّب بنفسي\nمن المتحدث؟ اذكر شخصين من أسرته. أكمل: «هذه ...» عند الإشارة إلى الأم.\n\nأتحقّق من إجابتي\nالمتحدث جاسم؛ الأب والأم؛ «هذه أمي».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ جملتين عن الأسرة ويحدد أفرادها.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"أسرة","meaning":"أفراد يعيشون بينهم صلة قرابة"},{"word":"أبي","meaning":"والدي"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":2,"title":"التراكيب اللغوية: الجمل القصيرة (من كلمتين)","lessonType":"grammar","objective":"يركب جملة مفيدة من كلمتين بترتيب صحيح","content":"التراكيب اللغوية: الجمل القصيرة (من كلمتين)\n\nأهداف التعلّم\n• يركب جملة مفيدة من كلمتين بترتيب صحيح.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالجملة القصيرة تعطي معنى مفهومًا، ويمكن أن تتكون من كلمتين. مثال: «جاسم حاضر». الكلمة الأولى تخبرنا عمن نتحدث، والثانية توضح حاله. أقرأ الكلمتين معًا ثم أعيدهما في جملة أخرى.\n\nأقرأ وألاحظ\nجاسم حاضر. البيت واسع. أمي هنا.\n\nأتدرّب بنفسي\nرتب «واسع / البيت». كوّن جملة من «أبي» وكلمة تختارها. هل «البيت في» جملة تامة المعنى؟\n\nأتحقّق من إجابتي\nالبيت واسع؛ مثال «أبي حاضر»؛ لا، لأنها لا تتم المعنى.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يركب جملة مفيدة من كلمتين بترتيب صحيح.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"جملة","meaning":"كلمات مرتبة تعطي معنى"},{"word":"واسع","meaning":"كبير المساحة"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":3,"title":"الإملاء والخط: رسم الكلمات بحسب التنقيط؛ مراعاة الحركات والمدود بأنواعها","lessonType":"spelling","objective":"يميّز النقاط والحركات القصيرة والمدود أثناء الكتابة","content":"الإملاء والخط: رسم الكلمات بحسب التنقيط؛ مراعاة الحركات والمدود بأنواعها\n\nأهداف التعلّم\n• يميّز النقاط والحركات القصيرة والمدود أثناء الكتابة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nأكتب الحروف في مواضعها وأضع النقاط بعناية: ب نقطة واحدة أسفل، ت نقطتان أعلى، ث ثلاث نقاط أعلى. وتغيّر الحركات الصوت: بَ، بُ، بِ. الحرف الممدود يستغرق صوتًا أطول: با، بو، بي. لا أخلط بين علامة الحركة وحرف المد.\n\nأقرأ وألاحظ\nبَ / با، بُ / بو، بِ / بي. باب، بيت، تين.\n\nأتدرّب بنفسي\nكم نقطة في «ت»؟ اختر الأطول صوتًا: «بَ» أم «با»؟ انسخ «بيت» مع وضع النقط.\n\nأتحقّق من إجابتي\nنقطتان؛ «با» أطول؛ كتابة «بيت» مع نقطتي الياء ونقطتي التاء.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميّز النقاط والحركات القصيرة والمدود أثناء الكتابة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"مد","meaning":"إطالة صوت الحرف"},{"word":"حركة","meaning":"فتحة أو ضمة أو كسرة"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":4,"title":"القراءة: الدرس الثاني: أسرة جاسم (2)","lessonType":"reading","objective":"يقرأ جملًا مترابطة عن الأسرة ويستخرج معلومة صريحة","content":"القراءة: الدرس الثاني: أسرة جاسم (2)\n\nأهداف التعلّم\n• يقرأ جملًا مترابطة عن الأسرة ويستخرج معلومة صريحة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nنتدرّب بموقف مستقل: «عادت أمي إلى البيت. جلس أبي قرب الباب. قرأ جاسم بطاقةً صغيرة». هذا النص التدريبي من تأليف ضاديوم ولا يحل محل نص الكتاب الأصلي. أتتبع كل كلمة بإصبعي وأحدد من قام بالفعل.\n\nأقرأ وألاحظ\nعادت أمي. جلس أبي. قرأ جاسم.\n\nأتدرّب بنفسي\nمن الذي عاد إلى البيت؟ أين جلس الأب؟ من قرأ البطاقة؟ اقرأ الجملة الثانية منفردًا.\n\nأتحقّق من إجابتي\nالأم؛ قرب الباب؛ جاسم. والجملة الثانية «جلس أبي قرب الباب».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ جملًا مترابطة عن الأسرة ويستخرج معلومة صريحة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"عاد","meaning":"رجع"},{"word":"بطاقة","meaning":"ورقة صغيرة تحمل معلومات"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":5,"title":"التراكيب اللغوية: الجمل القصيرة (من كلمتين أو ثلاث)","lessonType":"grammar","objective":"يكون جملًا من كلمتين أو ثلاث كلمات مناسبة للموقف","content":"التراكيب اللغوية: الجمل القصيرة (من كلمتين أو ثلاث)\n\nأهداف التعلّم\n• يكون جملًا من كلمتين أو ثلاث كلمات مناسبة للموقف.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nنبدأ من جملة مفيدة من كلمتين، ثم نضيف كلمة تحدد المكان أو الزمان: «جاسم يقرأ» تصبح «جاسم يقرأ اليوم». إضافة كلمة مناسبة تزيد المعنى وتجعله أوضح؛ وليست كل مجموعة كلمات جملة مفيدة.\n\nأقرأ وألاحظ\nأمي تعمل ← أمي تعمل اليوم. أبي يجلس ← أبي يجلس هنا.\n\nأتدرّب بنفسي\nوسع «جاسم يكتب» بكلمة واحدة. اختر الجملة الصحيحة: «أمي هنا» أم «هنا أمي في».\n\nأتحقّق من إجابتي\nمثال «جاسم يكتب اليوم»؛ «أمي هنا».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يكون جملًا من كلمتين أو ثلاث كلمات مناسبة للموقف.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"يوضح","meaning":"يجعل المعنى أبين"},{"word":"اليوم","meaning":"هذا النهار"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":6,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرف المستهدف (ج)","lessonType":"spelling","objective":"يفكك كلمات بسيطة إلى حروف ومقاطع ويحدد الجيم","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرف المستهدف (ج)\n\nأهداف التعلّم\n• يفكك كلمات بسيطة إلى حروف ومقاطع ويحدد الجيم.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالحرف المستهدف ج، وله نقطة واحدة تحت جسم الحرف. أنطق: جَ، جُ، جِ؛ ثم أمدّ الصوت: جا، جو، جي. في كلمة «جمل» أسمع الجيم في البداية، وفي «دجاج» أسمعها مرتين. أكتب الجيم بأشكالها بحسب موضعها.\n\nأقرأ وألاحظ\nجَ + مَ + ل = جَمَل. جا + سِم = جاسم (أعيد قراءة الاسم متصلًا).\n\nأتدرّب بنفسي\nما الحرف الأول في «جمل»؟ كم مرة يظهر «ج» في «دجاج»؟ انسخ «جاسم» وضع نقطة الجيم.\n\nأتحقّق من إجابتي\nحرف ج؛ مرتان؛ تُكتب الجيم بنقطة أسفل الحرف.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يفكك كلمات بسيطة إلى حروف ومقاطع ويحدد الجيم.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"مقطع","meaning":"جزء صوتي من كلمة"},{"word":"جمل","meaning":"حيوان معروف في الصحراء"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":7,"title":"القراءة: الدرس الثالث: زيارة إلى بيت جاسم (1)","lessonType":"reading","objective":"يقرأ نصًا تدريبيًا قصيرًا عن الزيارة ويحدد مكان الحدث","content":"القراءة: الدرس الثالث: زيارة إلى بيت جاسم (1)\n\nأهداف التعلّم\n• يقرأ نصًا تدريبيًا قصيرًا عن الزيارة ويحدد مكان الحدث.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nنص ضاديوم التدريبي: «زار سامي بيت جاسم. فتح جاسم الباب. قال سامي: السلام عليكم. رحّب جاسم بضيفه». ليست هذه عبارات نص الكتاب، بل مثال تعليمي أصلي. أنتبه لترتيب الأحداث: جاء الضيف ثم فُتح الباب ثم بدأت التحية.\n\nأقرأ وألاحظ\nزار سامي بيت جاسم. رحّب جاسم بضيفه.\n\nأتدرّب بنفسي\nإلى أين ذهب سامي؟ من فتح الباب؟ أي حدث وقع أولًا: التحية أم الوصول؟\n\nأتحقّق من إجابتي\nإلى بيت جاسم؛ جاسم؛ الوصول وقع أولًا.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ نصًا تدريبيًا قصيرًا عن الزيارة ويحدد مكان الحدث.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"زيارة","meaning":"الذهاب إلى شخص للقائه"},{"word":"ضيف","meaning":"شخص يأتي لزيارة آخر"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":8,"title":"التراكيب اللغوية: أسلوب الاستفهام","lessonType":"grammar","objective":"يستخدم أدوات الاستفهام للسؤال عن شخص أو مكان أو شيء","content":"التراكيب اللغوية: أسلوب الاستفهام\n\nأهداف التعلّم\n• يستخدم أدوات الاستفهام للسؤال عن شخص أو مكان أو شيء.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالسؤال يحتاج أداة مناسبة وعلامة استفهام في آخره. «من؟» للسؤال عن الشخص، و«أين؟» للمكان، و«ماذا؟» عن الشيء أو الفعل. أستمع إلى الجواب المتوقع قبل اختيار الأداة.\n\nأقرأ وألاحظ\nمن جاء؟ جاء سامي. أين البيت؟ البيت قريب. ماذا تقرأ؟ أقرأ بطاقة.\n\nأتدرّب بنفسي\nأكمل: «... جاء؟» للجواب «جاسم». اختر أداة للسؤال عن المدرسة. ضع علامة الترقيم: «أين أبي».\n\nأتحقّق من إجابتي\nمن جاء؟ أين المدرسة؟ «أين أبي؟».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يستخدم أدوات الاستفهام للسؤال عن شخص أو مكان أو شيء.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"استفهام","meaning":"طلب معرفة شيء بالسؤال"},{"word":"أين","meaning":"أداة للسؤال عن المكان"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":9,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرف المستهدف (م)؛ رسم الكلمات بحسب التنقيط","lessonType":"spelling","objective":"يميّز حرف الميم ويحلل كلمات تحويه صوتيًا وكتابيًا","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرف المستهدف (م)؛ رسم الكلمات بحسب التنقيط\n\nأهداف التعلّم\n• يميّز حرف الميم ويحلل كلمات تحويه صوتيًا وكتابيًا.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالميم (م) ليس له نقاط. أنطق: مَ، مِ، مُ، ثم ألاحظ المد: ما، مي، مو. يتصل الميم أحيانًا بما بعده، ويختلف رسمه باختلاف موقعه. أركب أصوات «مَ + ا» فأحصل على «ما».\n\nأقرأ وألاحظ\nماء، أم، قلم. في «ماء» الميم في أول الكلمة، وفي «قلم» في آخرها.\n\nأتدرّب بنفسي\nحدد الميم في «قلم». اكتب مقطعين من «مَ، مِ، مُ» وأطل صوت أحدهما بحرف المد المناسب. هل للميم نقطة؟\n\nأتحقّق من إجابتي\nالحرف الأخير؛ مثال «ما» و«مي»؛ لا، ليس له نقطة.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميّز حرف الميم ويحلل كلمات تحويه صوتيًا وكتابيًا.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"قلم","meaning":"أداة للكتابة"},{"word":"ماء","meaning":"شراب أساسي للحياة"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":10,"title":"القراءة: الدرس الرابع: زيارة إلى بيت جاسم (2)","lessonType":"reading","objective":"يقرأ تسلسلًا قصيرًا ويبين ختام زيارة","content":"القراءة: الدرس الرابع: زيارة إلى بيت جاسم (2)\n\nأهداف التعلّم\n• يقرأ تسلسلًا قصيرًا ويبين ختام زيارة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nنص تدريبي أصلي: «جلس الضيف في المجلس. قدّم جاسم الماء. شكر سامي جاسمًا. وبعد الزيارة قال: إلى اللقاء». أتوقف عند كل نقطة، وأقرأ التحية بوضوح. هذا مثال مؤلف لضاديوم ولا ينقل محتوى درس الزيارة الرسمي.\n\nأقرأ وألاحظ\nقدّم جاسم الماء. شكر سامي جاسمًا.\n\nأتدرّب بنفسي\nماذا قدّم جاسم للضيف؟ ماذا قال الضيف عند المغادرة؟ لماذا يشكر الضيف مضيفه؟\n\nأتحقّق من إجابتي\nالماء؛ «إلى اللقاء»؛ شكرًا لحسن الاستقبال (إجابة نموذجية).\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ تسلسلًا قصيرًا ويبين ختام زيارة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"المجلس","meaning":"مكان جلوس الضيوف"},{"word":"المغادرة","meaning":"الانصراف من المكان"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":11,"title":"التراكيب اللغوية: الفعل الماضي؛ الجملة الفعلية","lessonType":"grammar","objective":"يتعرف الفعل الماضي ويكوّن به جملة فعلية بسيطة","content":"التراكيب اللغوية: الفعل الماضي؛ الجملة الفعلية\n\nأهداف التعلّم\n• يتعرف الفعل الماضي ويكوّن به جملة فعلية بسيطة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالفعل الماضي يدل غالبًا على حدث وقع وانتهى قبل لحظة الكلام: زار، جلس، كتب. قد تبدأ الجملة بالفعل وتليه كلمة توضح من قام به: «زار سامي». أنطق الفعل أولًا ثم أذكر الفاعل، مع المحافظة على المعنى.\n\nأقرأ وألاحظ\nقرأ جاسم. رجع أبي. دخل الضيف.\n\nأتدرّب بنفسي\nاختر الماضي: «يكتب» أم «كتب»؟ رتب «أمي / حضرت». حوّل «يقرأ سامي» إلى الماضي.\n\nأتحقّق من إجابتي\nكتب؛ حضرت أمي؛ قرأ سامي.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يتعرف الفعل الماضي ويكوّن به جملة فعلية بسيطة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"فعل","meaning":"كلمة تدل على حدث"},{"word":"ماضٍ","meaning":"حدث وقع قبل وقت الكلام"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":12,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (د، ر)؛ تركيب كلمات من الحروف والمقاطع؛ رسم الكلمات بحسب التنقيط","lessonType":"spelling","objective":"يميّز الدال والراء ويركب كلمات ويفرق بين شكلي الحرفين","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (د، ر)؛ تركيب كلمات من الحروف والمقاطع؛ رسم الكلمات بحسب التنقيط\n\nأهداف التعلّم\n• يميّز الدال والراء ويركب كلمات ويفرق بين شكلي الحرفين.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالدال (د) والراء (ر) بلا نقاط، ولا يتصلان بالحرف الذي بعدهما في الكتابة. نقرأ «دار» من د + ا + ر، و«ورد» من و + ر + د. ألاحظ أن الدال لا يشبه الراء في اتجاه القلم أو شكل الجسم.\n\nأقرأ وألاحظ\nدَ، دُ، دِ؛ رَ، رُ، رِ. دار، دور، ورد.\n\nأتدرّب بنفسي\nحدد موضع الدال في «ورد». ركب «د + ا + ر». اكتب «د» و«ر» على السطر دون نقاط.\n\nأتحقّق من إجابتي\nفي آخر الكلمة؛ دار؛ الحرفان بلا نقاط.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميّز الدال والراء ويركب كلمات ويفرق بين شكلي الحرفين.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"دار","meaning":"بيت"},{"word":"ورد","meaning":"زهور"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":13,"title":"القراءة: الدرس الخامس: رحلة","lessonType":"reading","objective":"يقرأ نصًا أصليًا عن رحلة ويستخرج وجهتها ووسيلة النقل","content":"القراءة: الدرس الخامس: رحلة\n\nأهداف التعلّم\n• يقرأ نصًا أصليًا عن رحلة ويستخرج وجهتها ووسيلة النقل.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nنص ضاديوم: «خرج جاسم مع أسرته صباحًا. ركبوا الحافلة إلى الحديقة. شاهدوا الأشجار. عادوا قبل المساء». القراءة هنا تدريب إضافي أصلي وليست نسخة من درس «رحلة» المقرر. أميز بين بداية الرحلة ونهايتها.\n\nأقرأ وألاحظ\nذهبوا إلى الحديقة. عادوا قبل المساء.\n\nأتدرّب بنفسي\nمع من خرج جاسم؟ إلى أين ذهبوا؟ ما وسيلة النقل؟ متى عادوا؟\n\nأتحقّق من إجابتي\nمع أسرته؛ إلى الحديقة؛ الحافلة؛ قبل المساء.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ نصًا أصليًا عن رحلة ويستخرج وجهتها ووسيلة النقل.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"رحلة","meaning":"خروج لزيارة مكان"},{"word":"حافلة","meaning":"وسيلة نقل جماعية"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":14,"title":"التراكيب اللغوية: استعمال بعض ظروف الزمان والمكان (داخل، خارج، بعد، قبل)","lessonType":"grammar","objective":"يوظف داخل وخارج وقبل وبعد لتحديد المكان والزمان","content":"التراكيب اللغوية: استعمال بعض ظروف الزمان والمكان (داخل، خارج، بعد، قبل)\n\nأهداف التعلّم\n• يوظف داخل وخارج وقبل وبعد لتحديد المكان والزمان.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\n«داخل» و«خارج» تدلان على موضع الشيء؛ «قبل» و«بعد» تدلان على ترتيب الأحداث في الزمان أو غيره من الترتيب. أنظر إلى سياق الجملة: «الكتاب داخل الحقيبة»، و«أغسل يدي قبل الطعام». لا أستبدل «قبل» بـ«بعد» دون تغيّر المعنى.\n\nأقرأ وألاحظ\nجلس جاسم داخل البيت. لعب خارج البيت. رجع بعد العمل.\n\nأتدرّب بنفسي\nأكمل: «القلم ... الحقيبة» عند وضعه فيها. «أنام ... صلاة العشاء» هل الأنسب بعد أم قبل؟ ما ضد خارج؟\n\nأتحقّق من إجابتي\nداخل؛ بعد؛ داخل.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يوظف داخل وخارج وقبل وبعد لتحديد المكان والزمان.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"ظرف","meaning":"لفظ يدل على زمان أو مكان"},{"word":"حقيبة","meaning":"وعاء نحمل فيه أغراضنا"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":15,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (خ، ظ)؛ تركيب كلمات من الحروف والمقاطع؛ رسم الكلمات بحسب التنقيط","lessonType":"spelling","objective":"يميز حرفي الخاء والظاء ويقرأ مقاطع وكلمات تحويهما","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (خ، ظ)؛ تركيب كلمات من الحروف والمقاطع؛ رسم الكلمات بحسب التنقيط\n\nأهداف التعلّم\n• يميز حرفي الخاء والظاء ويقرأ مقاطع وكلمات تحويهما.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالخاء (خ) له نقطة واحدة فوق جسم الحرف، والظاء (ظ) له نقطة واحدة أعلى الحرف. يختلف صوت خ عن صوت ظ؛ نستمع ونردد قبل الكتابة. أقرأ «خُبز» و«ظِلّ» وألاحظ مكان النقطة واتصال الحروف.\n\nأقرأ وألاحظ\nخَ، خُ، خِ: خبز، أخ. ظَ، ظُ، ظِ: ظل، ظرف.\n\nأتدرّب بنفسي\nأي الحرفين يبدأ كلمة «خبز»؟ ضع نقطة الظاء في «ظرف». هل «أخ» تحتوي خ في أول الكلمة أم آخرها؟\n\nأتحقّق من إجابتي\nالخاء؛ نقطة فوق الظاء؛ الخاء في آخر «أخ».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميز حرفي الخاء والظاء ويقرأ مقاطع وكلمات تحويهما.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"ظل","meaning":"موضع لا تصل إليه الشمس مباشرة"},{"word":"ظرف","meaning":"غلاف أو كلمة للسياق بحسب الاستعمال"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":16,"title":"القراءة: الدرس السادس: سهرة عائلية","lessonType":"reading","objective":"يقرأ نصًا حواريًا قصيرًا عن سهرة عائلية","content":"القراءة: الدرس السادس: سهرة عائلية\n\nأهداف التعلّم\n• يقرأ نصًا حواريًا قصيرًا عن سهرة عائلية.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nمشهد تدريبي أصلي: «اجتمعت الأسرة مساءً. قال الأب: ماذا نقرأ؟ قالت الأم: نقرأ قصة قصيرة. استمع جاسم إلى القراءة». أقرأ العبارات داخل الحوار بحسب المتحدث، وأنتبه إلى علامتي الاستفهام والنقطة. المشهد ليس نص الكتاب الرسمي.\n\nأقرأ وألاحظ\nقال الأب: «ماذا نقرأ؟» قالت الأم: «نقرأ قصة».\n\nأتدرّب بنفسي\nمتى اجتمعت الأسرة؟ من طرح السؤال؟ ما الذي اقترحته الأم؟ أعد قراءة السؤال بنبرة مناسبة.\n\nأتحقّق من إجابتي\nمساءً؛ الأب؛ قراءة قصة قصيرة.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ نصًا حواريًا قصيرًا عن سهرة عائلية.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"سهرة","meaning":"اجتماع مسائي"},{"word":"قصة","meaning":"حكاية لها أحداث"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":17,"title":"التراكيب اللغوية: الحوار","lessonType":"grammar","objective":"ينشئ حوارًا قصيرًا بالتناوب والتحية والسؤال والجواب","content":"التراكيب اللغوية: الحوار\n\nأهداف التعلّم\n• ينشئ حوارًا قصيرًا بالتناوب والتحية والسؤال والجواب.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالحوار تبادل منظم للكلام بين طرفين أو أكثر. أبدأ بتحية مناسبة، وأنصت جيدًا، ثم أجيب عن السؤال بكلمات واضحة. يمكن أن أستخدم: من، أين، كيف، ماذا. لا أقاطع المتحدث أثناء كلامه.\n\nأقرأ وألاحظ\nجاسم: السلام عليكم. سامي: وعليكم السلام. جاسم: كيف حالك؟ سامي: بخير، شكرًا.\n\nأتدرّب بنفسي\nاكتب رد التحية. أضف سؤالًا واحدًا بين شخصين عن المكان. من يتكلم أولًا بعد السؤال: السائل أم المجيب؟\n\nأتحقّق من إجابتي\nوعليكم السلام؛ مثال «أين بيتك؟»؛ المجيب عادةً.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["ينشئ حوارًا قصيرًا بالتناوب والتحية والسؤال والجواب.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"حوار","meaning":"تبادل الكلام"},{"word":"إنصات","meaning":"استماع باهتمام"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":18,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (ف، ق)؛ تركيب كلمات من الحروف والمقاطع؛ كتابة الكلمات بحسب الصور","lessonType":"spelling","objective":"يميز الفاء والقاف ويكتب كلمات تحتويهما في مواضع مختلفة","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (ف، ق)؛ تركيب كلمات من الحروف والمقاطع؛ كتابة الكلمات بحسب الصور\n\nأهداف التعلّم\n• يميز الفاء والقاف ويكتب كلمات تحتويهما في مواضع مختلفة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالفاء (ف) له نقطة واحدة فوق الحرف، والقاف (ق) له نقطتان فوقه في الرسم المعتاد. أنطق «فَ» ثم «قَ» وأشعر باختلاف مخرج الصوت. أقرأ كلمات من محيط الحياة اليومية وأكتب الحروف والنقاط معًا.\n\nأقرأ وألاحظ\nفَ: فم، فنجان، ملف. قَ: قلم، قمر، سوق.\n\nأتدرّب بنفسي\nكم نقطة على الفاء؟ كم نقطة على القاف؟ ما الحرف الأول من «قمر»؟ اختر كلمة تحتوي ف: «ملف» أم «قلم».\n\nأتحقّق من إجابتي\nواحدة؛ نقطتان؛ ق؛ ملف.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميز الفاء والقاف ويكتب كلمات تحتويهما في مواضع مختلفة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"فنجان","meaning":"وعاء صغير للشراب"},{"word":"قمر","meaning":"جرم يضيء ليلًا"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":19,"title":"القراءة: الدرس السابع: بيت جاسم","lessonType":"reading","objective":"يقرأ وصفًا موجزًا لبيت ويميز أجزاؤه الأساسية","content":"القراءة: الدرس السابع: بيت جاسم\n\nأهداف التعلّم\n• يقرأ وصفًا موجزًا لبيت ويميز أجزاؤه الأساسية.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nوصف ضاديوم الأصلي: «بيت جاسم قريب من الطريق. للبيت باب واسع ونافذة. يجلس جاسم مع أسرته في الغرفة». أتوقف عند نهاية الجملة، وأعيد تسمية الأشياء التي قرأتها. الوصف تمرين إضافي وليس نص «بيت جاسم» الرسمي.\n\nأقرأ وألاحظ\nللبيت باب واسع. للبيت نافذة.\n\nأتدرّب بنفسي\nما الأشياء التي توجد في البيت بحسب النص؟ أين يجلس جاسم؟ اختر كلمة تصف الباب.\n\nأتحقّق من إجابتي\nباب ونافذة وغرفة؛ في الغرفة؛ واسع.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ وصفًا موجزًا لبيت ويميز أجزاؤه الأساسية.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"نافذة","meaning":"فتحة يدخل منها الضوء والهواء"},{"word":"غرفة","meaning":"جزء من البيت"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":20,"title":"التراكيب اللغوية: استعمال الضمير (أنا)","lessonType":"grammar","objective":"يستخدم الضمير أنا عند الحديث عن نفسه بصياغة بسيطة","content":"التراكيب اللغوية: استعمال الضمير (أنا)\n\nأهداف التعلّم\n• يستخدم الضمير أنا عند الحديث عن نفسه بصياغة بسيطة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\n«أنا» ضمير يتكلم به الشخص عن نفسه؛ أقول: «أنا أقرأ»، «أنا أكتب»، «أنا أتعلم». عند الحديث عن شخص آخر نستخدم اسمه أو ضميرًا آخر. أكتب «أنا» مستقلة قبل الفعل أو الخبر المناسب.\n\nأقرأ وألاحظ\nأنا حاضر. أنا أقرأ كتابًا. أنا أحب أسرتي.\n\nأتدرّب بنفسي\nأكمل عن نفسك «أنا ...». اختر الجملة المناسبة للمتحدث: «أنا أكتب» أم «هو أكتب»؟\n\nأتحقّق من إجابتي\nمثال «أنا أعمل»؛ «أنا أكتب».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يستخدم الضمير أنا عند الحديث عن نفسه بصياغة بسيطة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"ضمير","meaning":"كلمة تحل محل اسم أو تدل على المتكلم"},{"word":"متكلم","meaning":"من يصدر عنه الكلام"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":21,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (ث، ن)؛ تركيب كلمات من الحروف والمقاطع","lessonType":"spelling","objective":"يميز الثاء والنون ويركب كلمات قصيرة تتضمنهما","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (ث، ن)؛ تركيب كلمات من الحروف والمقاطع\n\nأهداف التعلّم\n• يميز الثاء والنون ويركب كلمات قصيرة تتضمنهما.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالثاء (ث) لها ثلاث نقاط فوقها، والنون (ن) لها نقطة واحدة فوقها في رسمها منفصلة. أقرأ الحرف مع الحركات: ثَ، ثِ، ثُ؛ نَ، نِ، نُ. أشير إلى الحرف قبل نطقه لأتأكد من عدد النقاط.\n\nأقرأ وألاحظ\nثَ: ثوب، مثلث. نَ: نور، نهر، عين.\n\nأتدرّب بنفسي\nكم نقطة فوق ث؟ أي حرف يبدأ «نور»؟ حدد النون في «عين». اكتب «ثوب» مع نقاط الثاء.\n\nأتحقّق من إجابتي\nثلاث؛ ن؛ في آخر الكلمة؛ ثوب بثلاث نقاط فوق الثاء.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميز الثاء والنون ويركب كلمات قصيرة تتضمنهما.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"ثوب","meaning":"لباس"},{"word":"نهر","meaning":"مجرى ماء"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":22,"title":"القراءة: الدرس الثامن: حسن جار جاسم","lessonType":"reading","objective":"يقرأ موقفًا قصيرًا عن حسن الجوار ويستنتج عملًا طيبًا","content":"القراءة: الدرس الثامن: حسن جار جاسم\n\nأهداف التعلّم\n• يقرأ موقفًا قصيرًا عن حسن الجوار ويستنتج عملًا طيبًا.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nنص تدريبي من ضاديوم: «رأى حسن جاره جاسمًا يحمل أكياسًا. قال حسن: هل تحتاج مساعدة؟ حمل معه كيسًا إلى الباب. شكر جاسم جاره». هذا النص أصلي لدعم مهارة القراءة، وليس نقلًا لدرس «حسن جار جاسم» من الكتاب.\n\nأقرأ وألاحظ\nساعد حسن جاره. شكر جاسم حسنًا.\n\nأتدرّب بنفسي\nما الذي كان يحمله جاسم؟ كيف ساعد حسن؟ لماذا شكر جاسم جاره؟ اقرأ السؤال الذي قاله حسن.\n\nأتحقّق من إجابتي\nأكياسًا؛ حمل معه كيسًا؛ لأنه ساعده. السؤال «هل تحتاج مساعدة؟».\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يقرأ موقفًا قصيرًا عن حسن الجوار ويستنتج عملًا طيبًا.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"جار","meaning":"من يسكن بالقرب منك"},{"word":"مساعدة","meaning":"عون نقدمه لغيرنا"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":23,"title":"التراكيب اللغوية: استعمال حروف الجر","lessonType":"grammar","objective":"يستخدم من وإلى وفي وعلى لتوضيح العلاقة في الجملة","content":"التراكيب اللغوية: استعمال حروف الجر\n\nأهداف التعلّم\n• يستخدم من وإلى وفي وعلى لتوضيح العلاقة في الجملة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nحروف الجر كلمات قصيرة تدخل قبل الأسماء: «من» تدل على ابتداء الغاية، و«إلى» على الاتجاه أو النهاية، و«في» على الظرفية، و«على» على الاستعلاء الحقيقي أو المجازي. في هذا المستوى نتدرب على المعنى العملي قبل المصطلحات.\n\nأقرأ وألاحظ\nخرجت من البيت. ذهبت إلى السوق. الكتاب في الحقيبة. القلم على المكتب.\n\nأتدرّب بنفسي\nاختر: «ذهبت ... السوق» (إلى/من). «الكتاب ... الحقيبة» (في/على) إذا كان داخلها. ما حرف الجر في «على المكتب»؟\n\nأتحقّق من إجابتي\nإلى؛ في؛ على.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يستخدم من وإلى وفي وعلى لتوضيح العلاقة في الجملة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"حرف جر","meaning":"كلمة تربط الاسم بما قبله"},{"word":"السوق","meaning":"مكان البيع والشراء"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":24,"title":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (س، ك)؛ تركيب كلمات من الحروف والمقاطع؛ كتابة الكلمات بحسب الصور؛ مراعاة التضعيف (الشدة) في الكلمات","lessonType":"spelling","objective":"يميّز السين والكاف ويفهم أثر الشدة أثناء القراءة والكتابة","content":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (س، ك)؛ تركيب كلمات من الحروف والمقاطع؛ كتابة الكلمات بحسب الصور؛ مراعاة التضعيف (الشدة) في الكلمات\n\nأهداف التعلّم\n• يميّز السين والكاف ويفهم أثر الشدة أثناء القراءة والكتابة.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nالسين (س) بلا نقاط، والكاف (ك) بلا نقاط. أنطق «سَ، سُ، سِ» و«كَ، كُ، كِ» وأقرأ كلمات تبدأ بهما. الشدة تعني أن الحرف يُنطق مشددًا؛ مثل «سَلَّمَ»، حيث اللام مشددة، ولا أضيف حرفًا جديدًا في الكتابة.\n\nأقرأ وألاحظ\nس: سمك، سوق، كرسي. ك: كتاب، كيس، مكتب. «سَلَّمَ» فيها شدة على اللام.\n\nأتدرّب بنفسي\nحدد الكاف في «مكتب». اختر كلمة فيها السين: «سمك» أم «قلم». أين الشدة في «سَلَّمَ»؟ اكتب «كيس».\n\nأتحقّق من إجابتي\nفي أول «مكتب»؟ لا؛ الكاف في وسطها بعد الميم والتاء. الكلمة «سمك»؛ الشدة على اللام؛ كتابة كيس بلا نقاط على الكاف.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يميّز السين والكاف ويفهم أثر الشدة أثناء القراءة والكتابة.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"شدة","meaning":"علامة على الحرف المشدد"},{"word":"كيس","meaning":"غلاف يحمل أشياء"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false},{"order":25,"title":"مراجعة عامة","lessonType":"assessment","objective":"يراجع مهارات القراءة والكتابة والتراكيب الأساسية في المستوى","content":"مراجعة عامة\n\nأهداف التعلّم\n• يراجع مهارات القراءة والكتابة والتراكيب الأساسية في المستوى.\n• يطبّق المتعلم الفكرة في مثال جديد من حياته اليومية.\n• يجيب عن أسئلة تحقق قصيرة بعد المحاولة الذاتية.\n\nأتعلّم\nمراجعة تجمع ما تعلمته في الجمل القصيرة، والحروف والنقاط، والسؤال، والفعل الماضي، وحروف الجر والضمير «أنا». اقرأ ببطء ثم حاول الإجابة قبل النظر إلى نموذج الإجابة. هذا تقويم تدريبي أصلي من ضاديوم، لا يمثل اختبار الوزارة.\n\nأقرأ وألاحظ\n«أنا أقرأ. زار سامي بيت جاسم. الكتاب في الحقيبة». حدد الضمير والفعل الماضي وحرف الجر.\n\nأتدرّب بنفسي\n1) كوّن جملة من «جاسم، حاضر». 2) اختر السؤال المناسب للجواب «في البيت». 3) حدد الماضي في «زار، يزور». 4) أكمل «القلم ... المكتب» إذا كان فوقه. 5) كم نقطة لحرف القاف؟\n\nأتحقّق من إجابتي\n1) جاسم حاضر. 2) أين جاسم؟ 3) زار. 4) على. 5) نقطتان.\n\nتطبيق من حياتي\nاكتب أو قل جملة قصيرة صحيحة تستخدم فيها فكرة الدرس؛ حاول شرح سبب اختيارك للحرف أو الكلمة، ثم أعد المحاولة عند الحاجة.\n\nملاحظة المصدر: هذا شرح وتدريب من تأليف ضاديوم، مبني على عنوان الدرس في خطة البحرين الرسمية، وليس نص الكتاب أو صورة منه. يحتاج إلى مراجعة تربوية نهائية قبل اعتباره مكافئًا لمحتوى الكتاب.","learning_objectives":["يراجع مهارات القراءة والكتابة والتراكيب الأساسية في المستوى.","يطبّق المتعلم المهارة في مثال جديد.","يجيب عن أسئلة تحقق قصيرة بمساعدة بسيطة عند الحاجة."],"vocabulary":[{"word":"مراجعة","meaning":"استعادة التعلم للتأكد من فهمه"},{"word":"تقويم","meaning":"التحقق من تحقق الهدف"}],"source":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","importedAt":"2026-10-08","originalSourcePlan":"https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf","bookTextCopied":false}]$DADYOOM$::jsonb)
),
scope AS (
 SELECT l.id,p.item
 FROM public.countries c
 JOIN public.curricula cur ON cur.country_id=c.id
 JOIN public.grades g ON g.curriculum_id=cur.id
 JOIN public.units u ON u.grade_id=g.id
 JOIN public.lessons l ON l.unit_id=u.id
 JOIN payload p ON l.lesson_number=(p.item->>'order')::integer AND l.title=(p.item->>'title')
 WHERE c.code='BH'
  AND cur.academic_year='2026-2027'
  AND cur.name_ar='اللغة العربية — التعليم المستمر'
  AND g.name_ar='الأول محو الأمية'
  AND g.grade_number IS NULL
  AND u.semester=1 AND l.semester=1
  AND l.official_content_scope='plan-scheduled'
  AND l.content='محتوى مقرر في الخطة الرسمية الحالية. يُحفظ العنوان كما في المصدر بعد تنظيف أخطاء OCR الشكلية فقط.'
)
UPDATE public.lessons l
 SET content=scope.item->>'content',
 learning_objectives=scope.item->'learning_objectives',
 vocabulary=scope.item->'vocabulary',
 instructions=COALESCE(l.instructions,'[]'::jsonb) || jsonb_build_array(jsonb_build_object(
  'kind','dadyoom_authored_content',
  'origin','DADYOOM_ORIGINAL_SUPPORTING_DRAFT',
  'editorial_review','required',
  'book_text_copied',false,
  'source_plan','https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf',
  'source_publication_ready',false
 )),
 estimated_minutes=30,
 updated_at=now()
 FROM scope WHERE l.id=scope.id;
